                    n = len(vecs_a[0][0])
                    dd = [mean([v[k] for v, _ in vecs_a]) - mean([v[k] for v, _ in vecs_c]) for k in range(n)]
                    pair["defects"] = n
                    pair["defect_diffs"] = dd
                    res["diffs"].extend(dd)
                else:
                    pair["defects"] = 0
            res["pairs"].append(pair)
        if metric == CATCH:
            res["unit"] = "defects"
        res["defect_identity"] = sorted(res["defect_identity"] - {"cap"})
